                (AuditActions.SpeechClipDeleted, AuditActions.SpeechClipObjectType, Guid.NewGuid(),
                    new { marker, MeetingId = s.MeetingId }),
            ];
            db.AuditLog.AddRange(rows.Select((r, i) => new AuditLogEntry
