        int? Pages(string name) => name switch { "Báo cáo Q3.pdf" => 12, "Tờ trình.pdf" => 3, "Phụ lục.pdf" => 1, _ => null };

        var body = await AssertCode(await client.PostAsync(s.Url, DocumentFixture.Form(files)), 201, "MSG161");

